//! Minimal HTTP/1.1 request parsing and response serialisation.

use std::fmt;
use std::io::{self, Read, Write};
use std::sync::Arc;

pub const MAX_HEADER_BYTES: usize = 64 * 1024;
pub const MAX_BODY_BYTES: usize = 1024 * 1024;

const READ_CHUNK: usize = 16 * 1024;

/// A request that cannot be served; carries the status code to reply with.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct HttpError(pub u16);

impl fmt::Display for HttpError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{} {}", self.0, reason_phrase(self.0))
    }
}

impl std::error::Error for HttpError {}

#[derive(Debug, Default)]
pub struct Request {
    pub method: String,
    pub target: String,
    pub headers: Vec<(String, String)>,
    pub body: Vec<u8>,
}

impl Request {
    /// Case-insensitive header lookup; returns the first match.
    pub fn header(&self, name: &str) -> Option<&str> {
        self.headers
            .iter()
            .find(|(k, _)| k.eq_ignore_ascii_case(name))
            .map(|(_, v)| v.as_str())
    }
}

#[derive(Debug, Clone)]
pub enum Body {
    Owned(Vec<u8>),
    Shared(Arc<Vec<u8>>),
}

impl Default for Body {
    fn default() -> Self {
        Body::Owned(Vec::new())
    }
}

impl AsRef<[u8]> for Body {
    fn as_ref(&self) -> &[u8] {
        match self {
            Body::Owned(v) => v,
            Body::Shared(v) => v,
        }
    }
}

#[derive(Debug, Clone, Default)]
pub struct Response {
    pub status: u16,
    pub content_type: Option<&'static str>,
    pub body: Body,
}

impl Response {
    pub fn status(status: u16) -> Self {
        Self {
            status,
            ..Self::default()
        }
    }

    pub fn with_body(status: u16, content_type: &'static str, body: Body) -> Self {
        Self {
            status,
            content_type: Some(content_type),
            body,
        }
    }

    /// Serialises the response, always with `Connection: close` and (except
    /// for 204) an exact `Content-Length`.
    pub fn write_to<W: Write>(&self, out: &mut W) -> io::Result<()> {
        let body = self.body.as_ref();
        let mut head = Vec::with_capacity(160);
        write!(
            head,
            "HTTP/1.1 {} {}\r\n",
            self.status,
            reason_phrase(self.status)
        )?;
        if let Some(ct) = self.content_type {
            write!(head, "Content-Type: {ct}\r\n")?;
        }
        // 204 must not carry a body or Content-Length framing.
        if self.status != 204 {
            write!(head, "Content-Length: {}\r\n", body.len())?;
        }
        head.extend_from_slice(b"Connection: close\r\n\r\n");

        if body.len() < READ_CHUNK {
            head.extend_from_slice(body);
            out.write_all(&head)?;
        } else {
            out.write_all(&head)?;
            out.write_all(body)?;
        }
        out.flush()
    }
}

pub fn reason_phrase(status: u16) -> &'static str {
    match status {
        200 => "OK",
        201 => "Created",
        204 => "No Content",
        400 => "Bad Request",
        404 => "Not Found",
        405 => "Method Not Allowed",
        408 => "Request Timeout",
        413 => "Content Too Large",
        431 => "Request Header Fields Too Large",
        500 => "Internal Server Error",
        501 => "Not Implemented",
        _ => "Unknown",
    }
}

fn trim(s: &str) -> &str {
    s.trim_matches([' ', '\t'])
}

/// Buffered reader over a byte stream with CRLF line framing.
struct Reader<R> {
    inner: R,
    buf: Vec<u8>,
    pos: usize,
}

impl<R: Read> Reader<R> {
    fn new(inner: R) -> Self {
        Self {
            inner,
            buf: Vec::new(),
            pos: 0,
        }
    }

    fn buffered(&self) -> usize {
        self.buf.len() - self.pos
    }

    /// Reads more bytes into the buffer; returns `false` on EOF.
    fn fill(&mut self) -> Result<bool, HttpError> {
        // Reclaim consumed space before growing.
        if self.pos > 0 && self.pos == self.buf.len() {
            self.buf.clear();
            self.pos = 0;
        }
        let start = self.buf.len();
        self.buf.resize(start + READ_CHUNK, 0);
        loop {
            match self.inner.read(&mut self.buf[start..]) {
                Ok(n) => {
                    self.buf.truncate(start + n);
                    return Ok(n > 0);
                }
                Err(e) if e.kind() == io::ErrorKind::Interrupted => continue,
                Err(_) => {
                    self.buf.truncate(start);
                    return Err(HttpError(408)); // timeout or connection error
                }
            }
        }
    }

    /// Returns the next CRLF-terminated line (without terminator).
    fn read_line(&mut self, limit: usize) -> Result<String, HttpError> {
        let mut from = self.pos;
        loop {
            if let Some(i) = self.buf[from..].windows(2).position(|w| w == b"\r\n") {
                let end = from + i;
                let line = String::from_utf8_lossy(&self.buf[self.pos..end]).into_owned();
                self.pos = end + 2;
                return Ok(line);
            }
            // Resume the search where it stopped, allowing for a split "\r\n".
            from = self.buf.len().saturating_sub(1).max(self.pos);
            if self.buffered() > limit {
                return Err(HttpError(431));
            }
            if !self.fill()? {
                return Err(HttpError(400));
            }
        }
    }

    fn read_exact_into(&mut self, n: usize, out: &mut Vec<u8>) -> Result<(), HttpError> {
        while self.buffered() < n {
            if !self.fill()? {
                return Err(HttpError(400));
            }
        }
        out.extend_from_slice(&self.buf[self.pos..self.pos + n]);
        self.pos += n;
        Ok(())
    }
}

fn parse_size(s: &str, radix: u32) -> Result<usize, HttpError> {
    // `from_str_radix` accepts a leading '+', which HTTP does not.
    if s.is_empty() || !s.bytes().all(|b| (b as char).is_digit(radix)) {
        return Err(HttpError(400));
    }
    usize::from_str_radix(s, radix).map_err(|_| HttpError(400))
}

fn read_chunked_body<R: Read>(reader: &mut Reader<R>, body: &mut Vec<u8>) -> Result<(), HttpError> {
    loop {
        let line = reader.read_line(MAX_HEADER_BYTES)?;
        let size_part = line.split_once(';').map_or(line.as_str(), |(s, _)| s);
        let size = parse_size(trim(size_part), 16)?;
        if size == 0 {
            break;
        }
        if size > MAX_BODY_BYTES || body.len() + size > MAX_BODY_BYTES {
            return Err(HttpError(413));
        }
        reader.read_exact_into(size, body)?;
        if !reader.read_line(0)?.is_empty() {
            return Err(HttpError(400));
        }
    }
    // Trailer section, terminated by an empty line.
    let mut total = 0;
    loop {
        let line = reader.read_line(MAX_HEADER_BYTES)?;
        if line.is_empty() {
            return Ok(());
        }
        total += line.len();
        if total > MAX_HEADER_BYTES {
            return Err(HttpError(431));
        }
    }
}

/// Reads one request. Returns `Ok(None)` if the peer closed the connection
/// before sending anything.
pub fn read_request<R: Read>(stream: R) -> Result<Option<Request>, HttpError> {
    let mut reader = Reader::new(stream);
    if !reader.fill()? {
        return Ok(None);
    }

    let mut request_line = reader.read_line(MAX_HEADER_BYTES)?;
    // Tolerate stray blank lines before the request line (RFC 9112 §2.2).
    while request_line.is_empty() {
        request_line = reader.read_line(MAX_HEADER_BYTES)?;
    }
    let mut header_bytes = request_line.len();

    let mut parts = request_line.splitn(3, ' ');
    let (Some(method), Some(target), Some(version)) = (parts.next(), parts.next(), parts.next())
    else {
        return Err(HttpError(400));
    };
    if method.is_empty() || target.is_empty() || !version.starts_with("HTTP/") {
        return Err(HttpError(400));
    }

    let mut req = Request {
        method: method.to_owned(),
        target: target.to_owned(),
        ..Request::default()
    };

    loop {
        let line = reader.read_line(MAX_HEADER_BYTES)?;
        if line.is_empty() {
            break;
        }
        header_bytes += line.len();
        if header_bytes > MAX_HEADER_BYTES {
            return Err(HttpError(431));
        }
        match line.split_once(':') {
            Some((name, value)) if !name.is_empty() => {
                req.headers.push((name.to_owned(), trim(value).to_owned()));
            }
            _ => return Err(HttpError(400)),
        }
    }

    if let Some(te) = req.header("Transfer-Encoding") {
        if !trim(te).eq_ignore_ascii_case("chunked") {
            return Err(HttpError(501));
        }
        let mut body = Vec::new();
        read_chunked_body(&mut reader, &mut body)?;
        req.body = body;
    } else if let Some(cl) = req.header("Content-Length") {
        let length = parse_size(trim(cl), 10)?;
        if length > MAX_BODY_BYTES {
            return Err(HttpError(413));
        }
        let mut body = Vec::with_capacity(length);
        reader.read_exact_into(length, &mut body)?;
        req.body = body;
    }
    Ok(Some(req))
}

#[cfg(test)]
mod tests {
    use super::*;

    fn parse(raw: &[u8]) -> Result<Option<Request>, HttpError> {
        read_request(raw)
    }

    #[test]
    fn parses_content_length_body() {
        let req = parse(b"PUT /kv/a HTTP/1.1\r\nContent-Length: 5\r\n\r\nhello")
            .unwrap()
            .unwrap();
        assert_eq!(req.method, "PUT");
        assert_eq!(req.target, "/kv/a");
        assert_eq!(req.body, b"hello");
    }

    #[test]
    fn parses_chunked_body() {
        let req = parse(
            b"PUT /kv/a HTTP/1.1\r\nTransfer-Encoding: chunked\r\n\r\n3\r\nhel\r\n2;x=y\r\nlo\r\n0\r\n\r\n",
        )
        .unwrap()
        .unwrap();
        assert_eq!(req.body, b"hello");
    }

    #[test]
    fn empty_stream_is_none() {
        assert!(parse(b"").unwrap().is_none());
    }

    #[test]
    fn rejects_malformed() {
        assert_eq!(parse(b"GET\r\n\r\n").unwrap_err(), HttpError(400));
        assert_eq!(
            parse(b"PUT /kv/a HTTP/1.1\r\nContent-Length: +1\r\n\r\nx").unwrap_err(),
            HttpError(400)
        );
        assert_eq!(
            parse(b"PUT /kv/a HTTP/1.1\r\nContent-Length: 2000000\r\n\r\n").unwrap_err(),
            HttpError(413)
        );
    }

    #[test]
    fn serialises_response() {
        let mut out = Vec::new();
        Response::with_body(200, "text/plain", Body::Owned(b"ok".to_vec()))
            .write_to(&mut out)
            .unwrap();
        assert_eq!(
            out,
            b"HTTP/1.1 200 OK\r\nContent-Type: text/plain\r\nContent-Length: 2\r\nConnection: close\r\n\r\nok"
        );
    }
}

//! kvhttp: an in-memory HTTP/1.1 key-value server.
//!
//! Usage: `app <port>` — listens on 127.0.0.1:<port> and serves until killed.

mod http;
mod router;
mod store;

use std::io::{self, Read};
use std::net::{Ipv4Addr, Shutdown, TcpListener, TcpStream};
use std::process::ExitCode;
use std::sync::Arc;
use std::thread;
use std::time::Duration;

use crate::http::{HttpError, Response};
use crate::router::Router;
use crate::store::Store;

const IO_TIMEOUT: Duration = Duration::from_secs(30);
const DRAIN_TIMEOUT: Duration = Duration::from_secs(2);
const MAX_DRAIN_BYTES: u64 = 64 * 1024 * 1024;

fn configure_client(stream: &TcpStream) -> io::Result<()> {
    stream.set_nodelay(true)?;
    stream.set_read_timeout(Some(IO_TIMEOUT))?;
    stream.set_write_timeout(Some(IO_TIMEOUT))
}

/// Discards unread request bytes (e.g. an oversized body we rejected) so that
/// closing does not trigger a RST that could clobber the reply.
fn drain(stream: &TcpStream) {
    if stream.set_read_timeout(Some(DRAIN_TIMEOUT)).is_ok() {
        let _ = io::copy(&mut stream.take(MAX_DRAIN_BYTES), &mut io::sink());
    }
}

fn serve_connection(stream: TcpStream, router: &Router) {
    if let Err(e) = configure_client(&stream) {
        eprintln!("kvhttp: configuring connection failed: {e}");
        return;
    }
    let response = match http::read_request(&stream) {
        Ok(Some(request)) => router.handle(request),
        Ok(None) => return,
        Err(HttpError(status)) => Response::status(status),
    };
    if response.write_to(&mut &stream).is_err() {
        return;
    }
    let _ = stream.shutdown(Shutdown::Write);
    drain(&stream);
}

fn parse_port(arg: &str) -> Option<u16> {
    if !arg.bytes().all(|b| b.is_ascii_digit()) {
        return None;
    }
    arg.parse().ok().filter(|&port| port != 0)
}

fn is_fd_exhaustion(e: &io::Error) -> bool {
    matches!(e.raw_os_error(), Some(libc::EMFILE | libc::ENFILE))
}

fn main() -> ExitCode {
    let args: Vec<String> = std::env::args().collect();
    let [_, port_arg] = args.as_slice() else {
        let prog = args.first().map_or("app", String::as_str);
        eprintln!("usage: {prog} <port>");
        return ExitCode::from(2);
    };
    let Some(port) = parse_port(port_arg) else {
        eprintln!("kvhttp: invalid port '{port_arg}'");
        return ExitCode::from(2);
    };

    let listener = match TcpListener::bind((Ipv4Addr::LOCALHOST, port)) {
        Ok(listener) => listener,
        Err(e) => {
            eprintln!("kvhttp: bind: {e}");
            return ExitCode::FAILURE;
        }
    };

    let router = Arc::new(Router::new(Store::new()));

    for conn in listener.incoming() {
        let stream = match conn {
            Ok(stream) => stream,
            Err(e)
                if matches!(
                    e.kind(),
                    io::ErrorKind::Interrupted | io::ErrorKind::ConnectionAborted
                ) =>
            {
                continue;
            }
            Err(e) if is_fd_exhaustion(&e) => {
                thread::sleep(Duration::from_millis(10));
                continue;
            }
            Err(e) => {
                eprintln!("kvhttp: accept: {e}");
                return ExitCode::FAILURE;
            }
        };
        let router = Arc::clone(&router);
        if let Err(e) = thread::Builder::new()
            .name("kvhttp-conn".into())
            .spawn(move || serve_connection(stream, &router))
        {
            // Could not spawn a worker; drop this connection and keep serving.
            eprintln!("kvhttp: thread spawn failed: {e}");
        }
    }
    ExitCode::SUCCESS
}

//! Maps requests onto the key/value API.

use crate::http::{Body, Request, Response};
use crate::store::Store;

const KV_PREFIX: &str = "/kv/";
const MAX_KEY_LENGTH: usize = 64;

/// True if `key` matches `[A-Za-z0-9_-]{1,64}`.
pub fn is_valid_key(key: &str) -> bool {
    (1..=MAX_KEY_LENGTH).contains(&key.len())
        && key
            .bytes()
            .all(|b| b.is_ascii_alphanumeric() || b == b'_' || b == b'-')
}

/// Keys are restricted to `[A-Za-z0-9_-]`, so no JSON escaping is required.
fn json_string_array(items: &[String]) -> Vec<u8> {
    let size = 2 + items.iter().map(|s| s.len() + 3).sum::<usize>();
    let mut out = Vec::with_capacity(size);
    out.push(b'[');
    for (i, item) in items.iter().enumerate() {
        if i > 0 {
            out.push(b',');
        }
        out.push(b'"');
        out.extend_from_slice(item.as_bytes());
        out.push(b'"');
    }
    out.push(b']');
    out
}

#[derive(Debug, Default)]
pub struct Router {
    store: Store,
}

impl Router {
    pub fn new(store: Store) -> Self {
        Self { store }
    }

    pub fn handle(&self, request: Request) -> Response {
        let Request {
            method,
            target,
            body,
            ..
        } = request;
        match target.as_str() {
            "/health" => match method.as_str() {
                "GET" => Response::with_body(200, "text/plain", Body::Owned(b"ok".to_vec())),
                _ => Response::status(405),
            },
            "/kv" => match method.as_str() {
                "GET" => Response::with_body(
                    200,
                    "application/json",
                    Body::Owned(json_string_array(&self.store.keys())),
                ),
                _ => Response::status(405),
            },
            path => match path.strip_prefix(KV_PREFIX) {
                Some(key) if is_valid_key(key) => self.handle_key(&method, key, body),
                Some(_) => Response::status(400),
                None => Response::status(404),
            },
        }
    }

    fn handle_key(&self, method: &str, key: &str, body: Vec<u8>) -> Response {
        match method {
            "GET" => match self.store.get(key) {
                Some(value) => {
                    Response::with_body(200, "application/octet-stream", Body::Shared(value))
                }
                None => Response::status(404),
            },
            "PUT" => {
                let created = self.store.put(key, body);
                Response::status(if created { 201 } else { 200 })
            }
            "DELETE" => Response::status(if self.store.remove(key) { 204 } else { 404 }),
            _ => Response::status(405),
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn req(method: &str, target: &str, body: &[u8]) -> Request {
        Request {
            method: method.into(),
            target: target.into(),
            body: body.to_vec(),
            ..Request::default()
        }
    }

    #[test]
    fn validates_keys() {
        assert!(is_valid_key("a-Z_09"));
        assert!(is_valid_key(&"k".repeat(64)));
        assert!(!is_valid_key(""));
        assert!(!is_valid_key(&"k".repeat(65)));
        assert!(!is_valid_key("a/b"));
        assert!(!is_valid_key("a.b"));
        assert!(!is_valid_key("é"));
    }

    #[test]
    fn routes() {
        let r = Router::default();
        assert_eq!(r.handle(req("GET", "/health", b"")).status, 200);
        assert_eq!(r.handle(req("POST", "/health", b"")).status, 405);
        assert_eq!(r.handle(req("GET", "/nope", b"")).status, 404);
        assert_eq!(r.handle(req("GET", "/kv/", b"")).status, 400);
        assert_eq!(r.handle(req("GET", "/kv/a/b", b"")).status, 400);
        assert_eq!(r.handle(req("PUT", "/kv/b", b"2")).status, 201);
        assert_eq!(r.handle(req("PUT", "/kv/a", b"1")).status, 201);
        assert_eq!(r.handle(req("PUT", "/kv/a", b"1")).status, 200);
        assert_eq!(r.handle(req("PATCH", "/kv/a", b"")).status, 405);
        assert_eq!(r.handle(req("POST", "/kv", b"")).status, 405);
        let list = r.handle(req("GET", "/kv", b""));
        assert_eq!(list.body.as_ref(), br#"["a","b"]"#);
        assert_eq!(r.handle(req("DELETE", "/kv/a", b"")).status, 204);
        assert_eq!(r.handle(req("DELETE", "/kv/a", b"")).status, 404);
        assert_eq!(r.handle(req("GET", "/kv/a", b"")).status, 404);
    }
}

//! Thread-safe in-memory key/value store.

use std::collections::BTreeMap;
use std::sync::{Arc, PoisonError, RwLock};

/// A stored value. Shared so readers can release the lock before copying
/// large values onto the wire.
pub type Value = Arc<Vec<u8>>;

#[derive(Debug, Default)]
pub struct Store {
    data: RwLock<BTreeMap<String, Value>>,
}

impl Store {
    pub fn new() -> Self {
        Self::default()
    }

    /// Stores `value` under `key`. Returns `true` if the key was newly created,
    /// `false` if it replaced an existing value.
    pub fn put(&self, key: &str, value: Vec<u8>) -> bool {
        let value = Arc::new(value);
        let mut data = self.data.write().unwrap_or_else(PoisonError::into_inner);
        match data.get_mut(key) {
            Some(slot) => {
                *slot = value;
                false
            }
            None => {
                data.insert(key.to_owned(), value);
                true
            }
        }
    }

    pub fn get(&self, key: &str) -> Option<Value> {
        let data = self.data.read().unwrap_or_else(PoisonError::into_inner);
        data.get(key).cloned()
    }

    /// Removes `key`. Returns `true` if it was present.
    pub fn remove(&self, key: &str) -> bool {
        let mut data = self.data.write().unwrap_or_else(PoisonError::into_inner);
        data.remove(key).is_some()
    }

    /// All keys in ascending byte order.
    pub fn keys(&self) -> Vec<String> {
        let data = self.data.read().unwrap_or_else(PoisonError::into_inner);
        data.keys().cloned().collect()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn put_get_remove() {
        let store = Store::new();
        assert!(store.put("a", b"1".to_vec()));
        assert!(!store.put("a", b"2".to_vec()));
        assert_eq!(
            store.get("a").as_deref().map(Vec::as_slice),
            Some(&b"2"[..])
        );
        assert!(store.remove("a"));
        assert!(!store.remove("a"));
        assert!(store.get("a").is_none());
    }

    #[test]
    fn keys_are_sorted() {
        let store = Store::new();
        for k in ["b", "a", "C", "_", "-"] {
            store.put(k, Vec::new());
        }
        assert_eq!(store.keys(), ["-", "C", "_", "a", "b"]);
    }
}
